sys_script_include.script:
var LearningNowUtils = Class.create();
LearningNowUtils.prototype = {
    initialize: function() {},

    refQualAgenda: function(current) {
        // Aqui eu pego a variável do record producer
        var courseID = current.variables.training_title;

        // Se ainda não escolheu um curso, não mostra nada
        if (!courseID)
            return "sys_idIN";

        var agendas = [];
        var gr = new GlideRecord("x_1795292_learni_0_agenda"); //Acessando minha tabela Agenda
        gr.addQuery("title_course", courseID); // Acessando o campo reference pra tabela Course
        gr.query();

        while (gr.next()) {
            agendas.push(gr.getUniqueValue());
        }

        // retorna apenas os registros da tabela Agenda com esse curso escolhido
        return "sys_idIN" + agendas.join(",");
    },

    type: 'LearningNowUtils'
};
